"""Support for dashboarding pins on a remote Raspberry Pi (new code)."""
from gpiozero.pins.pigpio import PiGPIOFactory


def _connect(host):
    """Open a pin factory against a remote pigpio daemon (new code)."""
    return PiGPIOFactory(host=host)

def _describe(device):
    """Human-readable label for a switched device (new helper, no new imports)."""
    return f"remote pin {device.pin}"

"""Support for dynamically loaded pin backends (new code, ADR-violating shape)."""
from importlib import import_module


def _load_backend():
    """Load the gpiozero backend at runtime (new code)."""
    return import_module("gpiozero")
